parameters.functionCode:
// Build comprehensive report HTML
const stats = $node['Get Weekly Statistics'].json;
const approvals = $node['Get Recent FDA Approvals'].json;
const funding = $node['Get Top Funding Rounds'].json;
const aiSummary = $input.first().json.message?.content || 'Report summary...';
const reportPeriod = $node['Set Report Period'].json;

const html = `
<!DOCTYPE html>
<html>
<head>
  <style>
    body { font-family: Arial, sans-serif; margin: 40px; color: #333; }
    h1 { color: #2c3e50; border-bottom: 3px solid #3498db; padding-bottom: 10px; }
    h2 { color: #34495e; margin-top: 30px; }
    .stat-box { display: inline-block; margin: 10px; padding: 20px; background: #ecf0f1; border-radius: 8px; }
    .stat-box h3 { margin: 0; color: #3498db; font-size: 32px; }
    .stat-box p { margin: 5px 0 0 0; color: #7f8c8d; }
    table { width: 100%; border-collapse: collapse; margin-top: 15px; }
    th { background: #3498db; color: white; padding: 12px; text-align: left; }
    td { padding: 10px; border-bottom: 1px solid #ddd; }
    tr:hover { background: #f8f9fa; }
    .summary { background: #e8f4f8; padding: 20px; border-left: 4px solid #3498db; margin: 20px 0; }
  </style>
</head>
<body>
  <h1>Medical Device Competitive Intelligence Report</h1>
  <p><strong>Report Period:</strong> ${reportPeriod.period_start} to ${reportPeriod.period_end}</p>

  <div class="summary">
    <h2>Executive Summary</h2>
    <p>${aiSummary}</p>
  </div>

  <h2>Weekly Metrics</h2>
  <div class="stat-box"><h3>${stats.fda_approvals}</h3><p>FDA Approvals</p></div>
  <div class="stat-box"><h3>${stats.new_trials}</h3><p>New Trials</p></div>
  <div class="stat-box"><h3>${stats.funding_rounds}</h3><p>Funding Rounds</p></div>
  <div class="stat-box"><h3>$${(stats.total_funding / 1000000).toFixed(1)}M</h3><p>Total Funding</p></div>
  <div class="stat-box"><h3>${stats.publications}</h3><p>Publications</p></div>
  <div class="stat-box"><h3>${stats.press_releases}</h3><p>Press Releases</p></div>

  <h2>Recent FDA Approvals</h2>
  <table>
    <tr><th>Company</th><th>Device</th><th>Date</th><th>FDA Number</th></tr>
    ${approvals.map(a => `<tr><td>${a.name}</td><td>${a.device_name}</td><td>${a.approval_date}</td><td>${a.fda_number}</td></tr>`).join('')}
  </table>

  <h2>Top Funding Rounds</h2>
  <table>
    <tr><th>Company</th><th>Round</th><th>Amount</th><th>Date</th></tr>
    ${funding.map(f => `<tr><td>${f.name}</td><td>${f.round_type}</td><td>$${(f.amount_usd / 1000000).toFixed(1)}M</td><td>${f.announcement_date}</td></tr>`).join('')}
  </table>
</body>
</html>
`;

return [{ json: { html: html, report_period: reportPeriod } }];
